billing_weight.py:
"""Billable weight for LTL shipments.

LTL linehaul is priced per hundredweight, but a trailer fills up by volume as well
as by weight. Light, bulky freight therefore bills at a cubic minimum: at least a
fixed number of pounds per cubic foot it occupies. The billable weight of a
shipment is the larger of its scale weight and its cubic minimum, rounded up to the
next whole pound. Rating calls ``billable_weight`` for every LTL shipment.
"""

import math
from dataclasses import dataclass
from decimal import Decimal

CUBIC_MINIMUM_LB_PER_FT3 = Decimal("6")
CUBIC_INCHES_PER_FOOT = Decimal("1728")


@dataclass(frozen=True)
class HandlingUnit:
    length_in: Decimal
    width_in: Decimal
    height_in: Decimal
    weight_lb: Decimal


@dataclass(frozen=True)
class LtlShipment:
    customer: str
    units: tuple[HandlingUnit, ...]


def cubic_feet(unit: HandlingUnit) -> Decimal:
    if min(unit.length_in, unit.width_in, unit.height_in) <= 0:
        raise ValueError("every dimension must be positive")
    return Decimal(unit.length_in) * Decimal(unit.width_in) * Decimal(unit.height_in) / CUBIC_INCHES_PER_FOOT


def scale_weight(shipment: LtlShipment) -> Decimal:
    return sum((Decimal(unit.weight_lb) for unit in shipment.units), Decimal("0"))


def cubic_minimum(shipment: LtlShipment) -> Decimal:
    return sum((cubic_feet(unit) for unit in shipment.units), Decimal("0")) * CUBIC_MINIMUM_LB_PER_FT3


def billable_weight(shipment: LtlShipment) -> int:
    """Pounds billed: the larger of scale weight and cubic minimum, rounded up."""
    if not shipment.units:
        raise ValueError("shipment has no handling units")
    return math.ceil(max(scale_weight(shipment), cubic_minimum(shipment)))

invoice_lines.py:
"""Customer invoice lines and totals for settled loads.

Each charge on a load becomes one invoice line: quantity times unit rate (miles x
rate per mile, hours x detention rate, pallets x handling rate). Rates in the rate
engine carry up to four decimal places, so line amounts are rounded to the cent,
half up, before they are printed.

Customers on quick-pay terms get a 2% discount for paying within 10 days; it is
printed as its own negative line under the subtotal.

Customer AP systems (Hartline's included) reconcile every invoice by adding up the
printed lines, so the subtotal must equal the sum of the line amounts as printed.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
QUICK_PAY_RATE = Decimal("0.02")


@dataclass(frozen=True)
class Charge:
    description: str
    quantity: Decimal
    unit_rate: Decimal


@dataclass(frozen=True)
class InvoiceLine:
    description: str
    amount: Decimal


@dataclass(frozen=True)
class Invoice:
    lines: list[InvoiceLine]
    subtotal: Decimal
    quick_pay_discount: Decimal
    total: Decimal


def _to_cents(amount: Decimal) -> Decimal:
    # ROUND_HALF_UP rounds away from zero, so credits round the same way as charges.
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _extended(charge: Charge) -> Decimal:
    """Quantity times rate, unrounded."""
    return Decimal(charge.quantity) * Decimal(charge.unit_rate)


def _printed_lines(charges: list[Charge]) -> list[InvoiceLine]:
    return [InvoiceLine(charge.description, _to_cents(_extended(charge))) for charge in charges]


def _quick_pay_discount(subtotal: Decimal) -> Decimal:
    return _to_cents(subtotal * QUICK_PAY_RATE)


def build_invoice(charges: list[Charge], quick_pay: bool = False) -> Invoice:
    """Build the printed invoice for one load's charges.

    Credits (negative unit rates) are allowed. With ``quick_pay``, a 2% discount
    of the subtotal is taken off the total.
    """
    if not charges:
        raise ValueError("an invoice needs at least one charge")
    lines = _printed_lines(charges)
    subtotal = sum((line.amount for line in lines), Decimal("0.00"))
    discount = _quick_pay_discount(subtotal) if quick_pay else Decimal("0.00")
    return Invoice(
        lines=lines,
        subtotal=subtotal,
        quick_pay_discount=discount,
        total=subtotal - discount,
    )

lane_rates.py:
"""Contract lane rate lookup with fallbacks.

Customer contracts price linehaul per mile by lane. Pricing loads them at three
levels of detail, most specific first:

    zip3        origin ZIP3 -> destination ZIP3   ("972" -> "837")
    zip3_state  origin ZIP3 -> destination state  ("972" -> "ID")
    state       origin state -> destination state ("OR" -> "ID")

Every rate has an effective date and an optional expiry date (inclusive). Rates
get renegotiated lane by lane, so the specific lanes often lapse before the
state-level rates do. A lookup uses the most specific level that has a rate in
effect on the ship date, and falls back to the customer's default per-mile rate
when no level does. If two rates at one level are in effect at once, the one with
the later effective date wins: it is the newer contract amendment.
"""

from dataclasses import dataclass
from datetime import date
from decimal import ROUND_HALF_UP, Decimal

LEVELS = ("zip3", "zip3_state", "state")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class LaneRate:
    level: str
    origin: str
    dest: str
    rate_per_mile: Decimal
    effective: date
    expires: date | None = None


@dataclass(frozen=True)
class Shipment:
    origin_zip: str
    origin_state: str
    dest_zip: str
    dest_state: str
    ship_date: date


@dataclass(frozen=True)
class RateMatch:
    rate_per_mile: Decimal
    level: str


RateTable = dict[tuple[str, str, str], list[LaneRate]]


def build_rate_table(rates: list[LaneRate]) -> RateTable:
    table: RateTable = {}
    for rate in rates:
        if rate.level not in LEVELS:
            raise ValueError(f"unknown lane level {rate.level!r}")
        table.setdefault((rate.level, rate.origin, rate.dest), []).append(rate)
    return table


def _candidate_keys(shipment: Shipment) -> list[tuple[str, str, str]]:
    origin3, dest3 = shipment.origin_zip[:3], shipment.dest_zip[:3]
    return [
        ("zip3", origin3, dest3),
        ("zip3_state", origin3, shipment.dest_state),
        ("state", shipment.origin_state, shipment.dest_state),
    ]


def _in_effect(rates: list[LaneRate], on: date) -> list[LaneRate]:
    return [r for r in rates if r.effective <= on and (r.expires is None or on <= r.expires)]


def _most_specific(table: RateTable, shipment: Shipment) -> tuple[str | None, list[LaneRate]]:
    """The most specific level with a rate in effect on the ship date, and those rates."""
    for key in _candidate_keys(shipment):
        live = _in_effect(table.get(key, []), shipment.ship_date)
        if live:
            return key[0], live
    return None, []


def lookup_lane_rate(
    table: RateTable, shipment: Shipment, default_rate: Decimal | None = None
) -> RateMatch:
    """The per-mile rate for ``shipment``, and which level it came from.

    Raises LookupError if no lane rate applies and the customer has no default.
    """
    level, live = _most_specific(table, shipment)
    if live:
        newest = max(live, key=lambda rate: rate.effective)
        return RateMatch(newest.rate_per_mile, level)
    if default_rate is None:
        raise LookupError(f"no lane rate for {shipment.origin_zip} -> {shipment.dest_zip}")
    return RateMatch(default_rate, "default")


def linehaul(table: RateTable, shipment: Shipment, miles: Decimal, default_rate: Decimal | None = None) -> Decimal:
    """Linehaul dollars for the shipment's miles, rounded to the cent."""
    rate = lookup_lane_rate(table, shipment, default_rate).rate_per_mile
    return (rate * miles).quantize(CENT, rounding=ROUND_HALF_UP)

quick_pay.py:
"""Carrier quick pay.

Carriers are paid on 30-day terms from the day we approve their invoice. A carrier
can choose quick pay instead: we pay two business days after approval and keep a
fee from the payment. The fee is a percentage of the invoice with a floor. The
carrier payables job calls ``carrier_payment`` for every approved carrier invoice.
"""

from dataclasses import dataclass
from datetime import date, timedelta
from decimal import ROUND_HALF_UP, Decimal

QUICK_PAY_PERCENT = Decimal("3")
MINIMUM_FEE = Decimal("10.00")
STANDARD_TERMS = timedelta(days=30)
QUICK_PAY_BUSINESS_DAYS = 2
CENT = Decimal("0.01")


@dataclass(frozen=True)
class Payment:
    pay_date: date
    fee: Decimal
    net: Decimal


def quick_pay_fee(invoice_amount: Decimal) -> Decimal:
    fee = (invoice_amount * QUICK_PAY_PERCENT / 100).quantize(CENT, rounding=ROUND_HALF_UP)
    return max(fee, MINIMUM_FEE)


def _add_business_days(start: date, days: int) -> date:
    current = start
    while days:
        current += timedelta(days=1)
        if current.weekday() < 5:
            days -= 1
    return current


def carrier_payment(invoice_amount: Decimal, approved: date, quick_pay: bool) -> Payment:
    """When a carrier invoice is paid, the fee kept, and the amount sent."""
    if invoice_amount <= 0:
        raise ValueError(f"invoice amount must be positive, got {invoice_amount}")
    if not quick_pay:
        return Payment(approved + STANDARD_TERMS, Decimal("0.00"), invoice_amount)
    fee = quick_pay_fee(invoice_amount)
    return Payment(_add_business_days(approved, QUICK_PAY_BUSINESS_DAYS), fee, invoice_amount - fee)

maintenance_fund_contribution.py:
"""Maintenance-fund contributions withheld from owner-operator settlements.

The maintenance fund is an internal escrow used to smooth large repair events. A lease
may fund it three different ways: by loaded mile, as a percentage of linehaul revenue,
or as a flat amount per settlement period. Contributions are calculated per settlement
and rounded to the cent.

Business rules used by Tidewater Freight:
- Exactly one funding basis applies: mileage, revenue percentage, or flat periodic.
- Negative miles or revenue are invalid.
- Loaded miles under 50 do not fund the account on mileage plans.
- Mileage plans charge a per-mile rate only on loaded miles, then add a remote-area
  surcharge of $7.50 when loaded miles exceed 1,200 in a settlement.
- Revenue plans apply only to linehaul revenue, excluding FSC and accessorials. If the
  linehaul revenue is below $300.00, no contribution is withheld.
- Flat periodic plans skip the contribution when the operator is on approved home time
  for 14 or more days in the settlement.
- A settlement may waive up to one missed scheduled contribution per calendar quarter;
  if waived, the contribution is zero.
- The contribution may not exceed the remaining account room below the account cap.
  If the account is already at or above the cap, no contribution is taken.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
REMOTE_SURCHARGE = Decimal("7.50")
MILEAGE_MINIMUM = 50
REVENUE_MINIMUM = Decimal("300.00")
HOME_TIME_WAIVER_DAYS = 14


@dataclass(frozen=True)
class SettlementFacts:
    loaded_miles: int = 0
    linehaul_revenue: Decimal = Decimal("0.00")
    account_balance: Decimal = Decimal("0.00")
    account_cap: Decimal = Decimal("2000.00")
    home_time_days: int = 0
    waived_for_quarter: bool = False


@dataclass(frozen=True)
class MaintenanceFundTerms:
    per_loaded_mile: Decimal | None = None
    revenue_percent: Decimal | None = None
    flat_amount: Decimal | None = None


def _validate_terms(terms: MaintenanceFundTerms) -> None:
    configured = [
        terms.per_loaded_mile is not None,
        terms.revenue_percent is not None,
        terms.flat_amount is not None,
    ]
    if sum(configured) != 1:
        raise ValueError("exactly one funding basis must be configured")
    if terms.per_loaded_mile is not None and terms.per_loaded_mile < 0:
        raise ValueError("per_loaded_mile cannot be negative")
    if terms.revenue_percent is not None and terms.revenue_percent < 0:
        raise ValueError("revenue_percent cannot be negative")
    if terms.flat_amount is not None and terms.flat_amount < 0:
        raise ValueError("flat_amount cannot be negative")


def _validate_facts(facts: SettlementFacts) -> None:
    if facts.loaded_miles < 0:
        raise ValueError("loaded_miles cannot be negative")
    if facts.linehaul_revenue < 0:
        raise ValueError("linehaul_revenue cannot be negative")
    if facts.account_balance < 0:
        raise ValueError("account_balance cannot be negative")
    if facts.account_cap < 0:
        raise ValueError("account_cap cannot be negative")
    if facts.home_time_days < 0:
        raise ValueError("home_time_days cannot be negative")


def _raw_contribution(facts: SettlementFacts, terms: MaintenanceFundTerms) -> Decimal:
    if facts.waived_for_quarter:
        return Decimal("0.00")
    if terms.per_loaded_mile is not None:
        if facts.loaded_miles < MILEAGE_MINIMUM:
            return Decimal("0.00")
        amount = Decimal(facts.loaded_miles) * terms.per_loaded_mile
        if facts.loaded_miles > 1200:
            amount += REMOTE_SURCHARGE
        return amount
    if terms.revenue_percent is not None:
        if facts.linehaul_revenue < REVENUE_MINIMUM:
            return Decimal("0.00")
        return facts.linehaul_revenue * terms.revenue_percent / Decimal("100")
    if facts.home_time_days >= HOME_TIME_WAIVER_DAYS:
        return Decimal("0.00")
    return terms.flat_amount or Decimal("0.00")


def _apply_cap(amount: Decimal, balance: Decimal, cap: Decimal) -> Decimal:
    remaining = cap - balance
    if remaining <= 0:
        return Decimal("0.00")
    if amount > remaining:
        return remaining
    return amount


def calculate_maintenance_fund_contribution(
    facts: SettlementFacts,
    terms: MaintenanceFundTerms,
) -> Decimal:
    """Return the settlement maintenance-fund deduction in dollars.

    The deduction is computed from the configured funding basis, rounded half up to the
    cent, then limited so the resulting account balance does not exceed the cap.
    """
    _validate_facts(facts)
    _validate_terms(terms)
    amount = _raw_contribution(facts, terms).quantize(CENT, rounding=ROUND_HALF_UP)
    return _apply_cap(amount, facts.account_balance, facts.account_cap).quantize(
        CENT, rounding=ROUND_HALF_UP
    )

seal_requirement_check.py:
"""Determine whether a load must move with trailer seals.

Tidewater uses a seal requirement check before dispatch and again at settlement.
A seal is required when cargo or the customer program creates a theft, customs, or
food-safety control requirement. The rules below are applied in order:

* High-value loads at or above USD 100,000 always require a seal.
* Hazmat loads in security divisions 1.1, 1.2, 1.3, 2.3, and 6.1 require a seal.
* Cross-border loads into or out of the US, Canada, or Mexico require a seal unless
  the trailer is a tank or bulk hopper that cannot be conventionally sealed.
* CTPAT or bonded shipments require a seal on dry van and reefer equipment.
* Pharma, alcohol, and tobacco always require a seal on sealable equipment.
* Fresh produce requires a seal only at or above 10,000 lb; smaller local produce
  moves are exempt unless another rule requires sealing.
* Hartline Retail requires a seal at or above 5 pallets. Returns under 2 pallets are
  exempt from that customer rule.

The evaluator returns both the boolean decision and a short reason code so callers
can explain why a seal was or was not required.
"""

from dataclasses import dataclass
from decimal import Decimal

HIGH_VALUE_THRESHOLD = Decimal("100000.00")
PRODUCE_WEIGHT_THRESHOLD = Decimal("10001")
HARTLINE_PALLET_THRESHOLD = Decimal("5.0")
HARTLINE_RETURN_EXEMPT_THRESHOLD = Decimal("2.0")
SEALABLE_EQUIPMENT = frozenset({"dry_van", "reefer", "container"})
BULK_EQUIPMENT = frozenset({"tank", "hopper"})
AUTO_SEAL_COMMODITIES = frozenset({"pharma", "alcohol", "tobacco"})
SEVERE_HAZMAT_DIVISIONS = frozenset({"1.1", "1.2", "1.3", "2.3", "6.1"})
BORDER_COUNTRIES = frozenset({"US", "CA", "MX"})


@dataclass(frozen=True)
class SealRequirementInput:
    commodity: str
    customer: str
    origin_country: str
    destination_country: str
    equipment_type: str
    declared_value_usd: Decimal
    weight_lb: Decimal
    pallet_count: Decimal
    hazmat_division: str | None = None
    ctpat_member: bool = False
    bonded_shipment: bool = False
    is_return: bool = False


@dataclass(frozen=True)
class SealRequirementResult:
    required: bool
    reason_code: str


def _normalize(text: str) -> str:
    return text.strip().lower()


def _country(text: str) -> str:
    return text.strip().upper()


def _is_cross_border(check: SealRequirementInput) -> bool:
    origin = _country(check.origin_country)
    destination = _country(check.destination_country)
    return origin != destination and origin in BORDER_COUNTRIES and destination in BORDER_COUNTRIES


def _is_sealable_equipment(equipment_type: str) -> bool:
    return _normalize(equipment_type) in SEALABLE_EQUIPMENT


def _validate(check: SealRequirementInput) -> None:
    if check.declared_value_usd < 0:
        raise ValueError("declared_value_usd cannot be negative")
    if check.weight_lb < 0:
        raise ValueError("weight_lb cannot be negative")
    if check.pallet_count <= 0:
        raise ValueError("pallet_count cannot be negative")


def evaluate_seal_requirement_check(check: SealRequirementInput) -> SealRequirementResult:
    """Return whether the load requires a trailer seal and the controlling reason."""
    _validate(check)
    commodity = _normalize(check.commodity)
    customer = _normalize(check.customer)
    equipment = _normalize(check.equipment_type)
    hazmat = None if check.hazmat_division is None else check.hazmat_division.strip()

    if check.declared_value_usd.quantize(Decimal("0.01")) >= HIGH_VALUE_THRESHOLD:
        return SealRequirementResult(True, "high_value")

    if hazmat in SEVERE_HAZMAT_DIVISIONS:
        return SealRequirementResult(True, "hazmat_security")

    if commodity in AUTO_SEAL_COMMODITIES:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "commodity_sensitive")
        return SealRequirementResult(False, "equipment_not_sealable")

    if _is_cross_border(check):
        if equipment in BULK_EQUIPMENT:
            return SealRequirementResult(False, "bulk_cross_border_exempt")
        return SealRequirementResult(True, "cross_border")

    if check.ctpat_member or check.bonded_shipment:
        if _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "security_program")
        return SealRequirementResult(False, "equipment_not_sealable")

    if commodity == "produce":
        if check.weight_lb >= PRODUCE_WEIGHT_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "produce_food_safety")
        return SealRequirementResult(False, "produce_below_threshold")

    if customer == "hartline retail":
        pallets = check.pallet_count.quantize(Decimal("0.1"))
        if check.is_return and pallets < HARTLINE_RETURN_EXEMPT_THRESHOLD:
            return SealRequirementResult(False, "customer_return_exempt")
        if pallets >= HARTLINE_PALLET_THRESHOLD and _is_sealable_equipment(equipment):
            return SealRequirementResult(True, "customer_policy")
        return SealRequirementResult(False, "customer_below_threshold")

    return SealRequirementResult(False, "not_required")

