    return datetime(*args, tzinfo=timezone.utc)


def test_offer_inside_business_hours():
    # Tue 2026-04-07 10:00 CDT
    assert tender_expires_at(utc(2026, 4, 7, 15, 0), CHICAGO) == utc(2026, 4, 7, 17, 0)


